* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #f3f5f8;
  color: #151820;
  font-family: Inter, Arial, sans-serif;
}

.app {
  min-height: 100vh;
  padding: 16px;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding: 12px 16px;
  background: #ffffff;
  border: 1px solid #dfe3e8;
  border-radius: 6px;
}

.toolbar div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.toolbar span {
  color: #68707d;
  font-size: 12px;
}

.toolbar button {
  border: 0;
  border-radius: 5px;
  padding: 10px 18px;
  background: #1d4ed8;
  color: #ffffff;
  font-weight: 700;
  cursor: pointer;
}

.empty {
  padding: 60px 20px;
  background: #ffffff;
  border: 1px dashed #c8ced8;
  border-radius: 6px;
  color: #68707d;
  text-align: center;
}

.label-grid {
  display: grid;
  gap: 5mm;
}

.layout-a4_4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.layout-a4_3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.layout-a4_2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.layout-single {
  grid-template-columns: minmax(0, 95mm);
  justify-content: center;
}

.label-card {
  display: flex;
  min-height: 48mm;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
  padding: 4mm;
  background: #ffffff;
  border: 1px solid #151820;
  border-radius: 4px;
  break-inside: avoid;
}

.label-card.discounted {
  border: 2px solid #c92127;
}

.label-card header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.company-name,
.product-code,
.sku {
  display: block;
}

.company-name {
  font-size: 9px;
  text-transform: uppercase;
}

.product-code,
.sku {
  margin-top: 2px;
  color: #68707d;
  font-size: 8px;
}

.discount-badge {
  padding: 4px 6px;
  background: #c92127;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
}

.label-card h2 {
  margin: 8px 0 5px;
  font-size: 13px;
  line-height: 1.2;
}

.price-row {
  display: flex;
  align-items: baseline;
  gap: 5px;
}

.current-price {
  font-size: 22px;
  font-weight: 900;
}

.price-row small {
  color: #68707d;
  font-size: 9px;
}

.lowest-price {
  display: flex;
  flex-direction: column;
  margin-top: 5px;
  color: #4b5260;
  font-size: 7px;
}

.lowest-price strong {
  margin-top: 2px;
  color: #151820;
  font-size: 9px;
}

.label-card footer {
  margin-top: 8px;
  text-align: center;
}

.label-card footer svg {
  width: 100%;
  max-width: 100%;
}

@page {
  size: A4 portrait;
  margin: 8mm;
}
@media print {
  body,
  .app {
    margin: 0;
    padding: 0;
    background: #ffffff;
  }
  .no-print {
    display: none !important;
  }
  .label-grid {
    gap: 4mm;
  }
  .label-card {
    border-radius: 0;
    box-shadow: none;
  }
}

