import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0/client";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function money(value, currency = "EUR") {
  return new Intl.NumberFormat("hr-HR", {
    style: "currency",
    currency
  }).format(Number(value || 0));
}

function normalize(row = {}) {
  const salesPrice = Number(
    row.salesPrice ??
    row.unitPrice ??
    row.price ??
    row["Sales Price"] ??
    0
  );

  const lowestPrice30Days = Number(
    row.lowestPrice30Days ??
    row["Lowest Price 30 Days"] ??
    salesPrice
  );

  const isDiscounted =
    row.isDiscounted === true ||
    row.isDiscounted === 1 ||
    row.isDiscounted === "1" ||
    lowestPrice30Days > salesPrice;

  const discountPercent = lowestPrice30Days > 0
    ? Math.round((1 - salesPrice / lowestPrice30Days) * 100)
    : 0;

  return {
    productId: row.productId || row.id,
    productCode: row.productCode || row.Code || row.code || "",
    productName: row.productName || row.Name || row.name || "Product",
    barcode: row.barcode || row.Barcode || row.productCode || "",
    sku: row.sku || row.SKU || "",
    unitCode: row.unitCode || row.Unit || "kom",
    salesPrice,
    lowestPrice30Days,
    isDiscounted,
    discountPercent: Number(row.discountPercent || discountPercent || 0),
    copies: Math.max(1, Number(row.copies || row.quantity || 1))
  };
}

function Barcode({ value }) {
  const ref = React.useRef(null);

  React.useEffect(() => {
    if (!value || !ref.current) return;

    try {
      JsBarcode(ref.current, String(value), {
        format: "CODE128",
        displayValue: true,
        fontSize: 10,
        height: 34,
        width: 1.25,
        margin: 0
      });
    } catch (error) {
      console.log("Barcode error:", error);
    }
  }, [value]);

  return <svg ref={ref}></svg>;
}

function ProductLabel({ label, company, currencyCode }) {
  return (
    <article className={`label-card ${label.isDiscounted ? "discounted" : ""}`}>
      <header>
        <div>
          <strong className="company-name">{company.name}</strong>
          <span className="product-code">{label.productCode}</span>
        </div>

        {label.isDiscounted && (
          <span className="discount-badge">
            -{label.discountPercent}%
          </span>
        )}
      </header>

      <main>
        <h2>{label.productName}</h2>

        <div className="price-row">
          <span className="current-price">
            {money(label.salesPrice, currencyCode)}
          </span>

          <small>/ {label.unitCode}</small>
        </div>

        {label.isDiscounted && (
          <div className="lowest-price">
            Najniža cijena u prethodnih 30 dana:
            <strong>{money(label.lowestPrice30Days, currencyCode)}</strong>
          </div>
        )}
      </main>

      <footer>
        <Barcode value={label.barcode} />

        {label.sku && (
          <span className="sku">SKU: {label.sku}</span>
        )}
      </footer>
    </article>
  );
}

function App() {
  const model = appsmith.model || {};
  const company = model.company || {};
  const currencyCode = model.currencyCode || "EUR";
  const layout = model.layout || "A4_4";

  const labels = (model.labels || [])
    .map(normalize)
    .flatMap(label =>
      Array.from({ length: label.copies }, () => ({ ...label }))
    );

  return (
    <div className="app">
      <div className="toolbar no-print">
        <div>
          <strong>Product Labels</strong>
          <span>{labels.length} label(s)</span>
        </div>

        <button onClick={() => window.print()}>
          Print Labels
        </button>
      </div>

      {!labels.length ? (
        <div className="empty no-print">
          Scan or select products to prepare labels.
        </div>
      ) : (
        <div className={`label-grid layout-${layout.toLowerCase()}`}>
          {labels.map((label, index) => (
            <ProductLabel
              key={`${label.productId}-${index}`}
              label={label}
              company={company}
              currencyCode={currencyCode}
            />
          ))}
        </div>
      )}
    </div>
  );
}

let root;

function render() {
  if (!root) {
    root = ReactDOM.createRoot(document.getElementById("root"));
  }

  root.render(<App />);
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
